def classify(text):
    row = vectorizer.transform([text])
    if row.nnz == 0:
        return 'Недостаточно знакомых слов'
    label = int(model.predict(row)[0])
    return ['Отрицательный', 'Положительный'][label]

assert classify('') == 'Недостаточно знакомых слов'
assert classify('неизвестная галактика') == 'Недостаточно знакомых слов'
for text in ['great food', 'bad service', 'неизвестная галактика']:
    print(text, '→', classify(text))
